import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for TokenBuffer.writeTree(TreeNode node).
 */
public class TokenBuffer_writeTree_TriageGen2Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Ensure consistent output for comparison
        mapper.configure(SerializationFeature.INDENT_OUTPUT, false);
        tokenBuffer = new TokenBuffer(mapper);
    }

    @Test
    public void testWriteTree_WithObjectNode() throws IOException {
        // Arrange
        ObjectNode root = mapper.createObjectNode();
        root.put("key", "value");
        root.put("number", 123);

        // Act
        tokenBuffer.writeTree(root);

        // Assert
        String json = getBufferContent();
        assertEquals("{\"key\":\"value\",\"number\":123}", json);
    }

    @Test
    public void testWriteTree_WithArrayNode() throws IOException {
        // Arrange
        ArrayNode arrayNode = mapper.createArrayNode();
        arrayNode.add(1);
        arrayNode.add("two");
        arrayNode.add(true);

        // Act
        tokenBuffer.writeTree(arrayNode);

        // Assert
        String json = getBufferContent();
        assertEquals("[1,\"two\",true]", json);
    }

    @Test
    public void testWriteTree_WithTextNode() throws IOException {
        // Arrange
        TextNode textNode = mapper.getNodeFactory().textNode("hello");

        // Act
        tokenBuffer.writeTree(textNode);

        // Assert
        String json = getBufferContent();
        assertEquals("\"hello\"", json);
    }

    @Test
    public void testWriteTree_WithNullNode() throws IOException {
        // Arrange
        JsonNode nullNode = mapper.getNodeFactory().nullNode();

        // Act
        tokenBuffer.writeTree(nullNode);

        // Assert
        String json = getBufferContent();
        assertEquals("null", json);
    }

    @Test
    public void testWriteTree_WithComplexTree() throws IOException {
        // Arrange
        ObjectNode root = mapper.createObjectNode();
        ArrayNode arr = mapper.createArrayNode();
        ObjectNode nested = mapper.createObjectNode();
        nested.put("id", 1);
        arr.add(nested);
        root.set("data", arr);

        // Act
        tokenBuffer.writeTree(root);

        // Assert
        String json = getBufferContent();
        assertEquals("{\"data\":[{\"id\":1}]}", json);
    }

    /**
     * Helper method to convert TokenBuffer content to String for assertion.
     */
    private String getBufferContent() throws IOException {
        // We use a dummy generator to write the buffer content to a string
        // Or more simply, use the mapper's ability to read the buffer via a parser
        JsonParser parser = tokenBuffer.asParser();
        if (parser == null) {
            return "";
        }

        // Since TokenBuffer implements JsonGenerator, we can use a custom approach 
        // or simply use the mapper to read it back.
        // The most reliable way to see what's in the buffer is to write it to a string.
        java.io.StringWriter writer = new java.io.StringWriter();
        JsonGenerator gen = mapper.getFactory().createGenerator(writer);
        tokenBuffer.serialize(gen);
        gen.close();
        return writer.toString();
    }
}
